import sys

def main():
    class Book:
        def __init__(self, title="", author="", year=0):
            self.title = title
            self.author = author
            self.year = year

        def __str__(self):
            return f"Title: {self.title}, Author: {self.author}, Year: {self.year}"

    n = int(sys.stdin.readline().strip())
    books = []

    for _ in range(n):
        line = sys.stdin.readline().strip()
        parts = line.rsplit(' ', 1)
        title_author = parts[0].rsplit(' ', 1)
        title = title_author[0]
        author = title_author[1] if len(title_author) > 1 else ""
        year = int(parts[1])
        books.append(Book(title, author, year))

    for book in books:
        print(book)

if __name__ == "__main__":
    main()
